import type { Job } from 'bullmq';
import Stripe from 'stripe';
import { db } from '../db';
import { syncState } from '../db/schema';
import { logger } from '../logger';
import { upsertInvoice } from '../stripe/upsert';

export const BILLING_SYNC_EVERY_MS = 15 * 60 * 1000;

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, { timeout: 10_000 });

export async function billingSync(job: Job<{ orgId: string }>) {
  const { orgId } = job.data;
  const state = await db.query.syncState.findFirst({ where: (s, { eq }) => eq(s.orgId, orgId) });
  const since = state?.lastRunAt ?? new Date(0);

  for await (const invoice of stripe.invoices.list({
    created: { gte: Math.floor(since.getTime() / 1000) },
    limit: 100,
  })) {
    await upsertInvoice(orgId, invoice);
  }

  await db.update(syncState).set({ lastRunAt: new Date() }).where(eq(syncState.orgId, orgId));
  logger.info({ orgId, since }, 'billing-sync done');
}

